    require_compute();d=folder('audit_detail');t=load(OUT/'prepare/roster.npz');mem=json.loads((OUT/'audit/three_membership.json').read_text());raw=json.loads((OUT/'audit/three_raw_imaging.json').read_text());scores={r['ls_id']:r for r in csv.DictReader((OLD/'examples/QRF_M13_lowerMS_per_star.csv').open())};centers=np.genfromtxt(ROOT/'data/reference/vasiliev_baumgardt_2021_clusters.txt',names=True,dtype=None,encoding='utf8');m13=next(r for r in centers if str(r['Name']).startswith('NGC_6205'));rows=[]
